<?php
declare(strict_types=1);
namespace Wams;
use PDO;
use RuntimeException;
final class Core{
 public array $cfg;public PDO $db;
 public function __construct(){ $this->cfg=require dirname(__DIR__).'/config/defaults.php';if(!is_dir($this->cfg['state'])&&!mkdir($this->cfg['state'],0770,true))throw new RuntimeException('State-Verzeichnis kann nicht angelegt werden.');if(!is_writable($this->cfg['state']))throw new RuntimeException('State-Verzeichnis ist für den Webserver nicht beschreibbar.');$this->db=new PDO('sqlite:'.$this->cfg['db'],null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$this->db->exec('PRAGMA foreign_keys=ON;PRAGMA journal_mode=WAL');$this->migrate();}
 public function installed():bool{return (bool)$this->db->query("SELECT count(*) FROM sqlite_master WHERE type='table' AND name='users'")->fetchColumn();}
 public function migrate():void{$sql=file_get_contents(dirname(__DIR__).'/migrations/001.sql');if($sql===false)throw new RuntimeException('Migration fehlt.');$this->db->exec($sql);$cols=$this->db->query('PRAGMA table_info(users)')->fetchAll();$names=array_column($cols,'name');if(!in_array('totp_secret',$names,true))$this->db->exec('ALTER TABLE users ADD COLUMN totp_secret TEXT');if(!in_array('totp_enabled',$names,true))$this->db->exec('ALTER TABLE users ADD COLUMN totp_enabled INTEGER NOT NULL DEFAULT 0');}
 public function id():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',[...str_split(bin2hex($b),4)]);}
 public function csrf():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return $_SESSION['csrf'];}
 public function check():void{if(!hash_equals((string)($_SESSION['csrf']??''),(string)($_POST['csrf']??'')))throw new RuntimeException('CSRF-Prüfung fehlgeschlagen.');}
 public function user():?array{if(empty($_SESSION['uid']))return null;$q=$this->db->prepare('SELECT * FROM users WHERE id=? AND active=1');$q->execute([$_SESSION['uid']]);return $q->fetch()?:null;}
 public function beginLogin(string $l,string $p):string{$q=$this->db->prepare('SELECT * FROM users WHERE active=1 AND (username=? OR email=?)');$q->execute([$l,$l]);$u=$q->fetch();if(!$u||!password_verify($p,$u['password_hash']))return 'invalid';if(!empty($u['totp_enabled'])&&!empty($u['totp_secret'])){$_SESSION['pending_uid']=$u['id'];return 'totp';}session_regenerate_id(true);$_SESSION['uid']=$u['id'];return 'ok';}
 public function login(string $l,string $p):bool{return $this->beginLogin($l,$p)==='ok';}
 public function finishTotp(string $code):bool{if(empty($_SESSION['pending_uid']))return false;$q=$this->db->prepare('SELECT * FROM users WHERE id=? AND active=1');$q->execute([$_SESSION['pending_uid']]);$u=$q->fetch();if(!$u||!$this->verifyTotp((string)$u['totp_secret'],$code))return false;session_regenerate_id(true);$_SESSION['uid']=$u['id'];unset($_SESSION['pending_uid']);return true;}
 private function verifyTotp(string $secret,string $code):bool{$alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$secret=strtoupper(preg_replace('/[^A-Z2-7]/','',$secret));$bits='';foreach(str_split($secret) as $ch){$v=strpos($alphabet,$ch);if($v===false)return false;$bits.=str_pad(decbin($v),5,'0',STR_PAD_LEFT);}$key='';for($i=0;$i+8<=strlen($bits);$i+=8)$key.=chr(bindec(substr($bits,$i,8)));$counter=(int)floor(time()/30);for($d=-1;$d<=1;$d++){$bin=pack('N*',0,$counter+$d);$hash=hash_hmac('sha1',$bin,$key,true);$o=ord($hash[19])&15;$n=((ord($hash[$o])&127)<<24)|((ord($hash[$o+1])&255)<<16)|((ord($hash[$o+2])&255)<<8)|(ord($hash[$o+3])&255);$expected=str_pad((string)($n%1000000),6,'0',STR_PAD_LEFT);if(hash_equals($expected,preg_replace('/\D/','',$code)))return true;}return false;}
 public function requireUser():array{$u=$this->user();if(!$u){header('Location:/login');exit;}return $u;}
 public function tenants(array $u):array{if($u['is_global'])return $this->db->query('SELECT * FROM tenants ORDER BY name')->fetchAll();$q=$this->db->prepare('SELECT t.* FROM tenants t JOIN user_tenants x ON x.tenant_id=t.id WHERE x.user_id=?');$q->execute([$u['id']]);return $q->fetchAll();}
 public function canTenant(array $u,string $tid):bool{if($u['is_global'])return true;$q=$this->db->prepare('SELECT 1 FROM user_tenants WHERE user_id=? AND tenant_id=?');$q->execute([$u['id'],$tid]);return (bool)$q->fetchColumn();}
 public function manifest(string $id):array{$f=$this->cfg['apps'].'/'.basename($id).'/app.json';$a=is_file($f)?json_decode((string)file_get_contents($f),true):null;if(!is_array($a))throw new RuntimeException('App fehlt.');return $a;}
 public function catalog():array{$o=[];foreach(glob($this->cfg['apps'].'/*/app.json')?:[] as $f){$a=json_decode((string)file_get_contents($f),true);if(is_array($a)&&($a['catalog']['discoverable']??false)&&($a['catalog']['installable']??false))$o[]=$a;}return $o;}
 public function instance(string $id):array{$q=$this->db->prepare('SELECT * FROM app_instances WHERE id=?');$q->execute([$id]);$i=$q->fetch();if(!$i)throw new RuntimeException('Instanz fehlt.');return $i;}
 public function config(string $id):array{$f=$this->cfg['state'].'/instances/'.$id.'/config.json';$x=is_file($f)?json_decode((string)file_get_contents($f),true):[];return is_array($x)?$x:[];}
 public function allowed(array $u,array $i,string $perm):bool{if($u['is_global'])return true;if(!$this->canTenant($u,$i['tenant_id']))return false;$q=$this->db->prepare("SELECT 1 FROM app_access a WHERE instance_id=? AND permission=? AND ((subject_type='tenant' AND subject_id=?) OR (subject_type='user' AND subject_id=?) OR (subject_type='group' AND EXISTS(SELECT 1 FROM group_users g WHERE g.group_id=a.subject_id AND g.user_id=?))) LIMIT 1");$q->execute([$i['id'],$perm,$i['tenant_id'],$u['id'],$u['id']]);return (bool)$q->fetchColumn();}
 public function remoteCheck(array $c):array{$url=(string)($c['remoteUrl']??'');if(!filter_var($url,FILTER_VALIDATE_URL))return[false,'Ungültige Remote-URL.'];$ctx=stream_context_create(['http'=>['timeout'=>max(2,min(60,(int)($c['timeoutSeconds']??20))),'ignore_errors'=>true,'header'=>"Accept: text/csv,text/plain\r\nUser-Agent: WAMS/1.2\r\n"]]);$d=@file_get_contents($url,false,$ctx);if($d===false)return[false,'Remote-Daten sind nicht erreichbar. Eventuell wird DNS blockiert. Versuche, sofern zulässig, die IP-Adresse statt des Hostnamens.'];return[true,'Erreichbar'];}
 public function install(string $tid,string $app,string $name,array $cfg,array $u,string $mode):string{if(!$this->canTenant($u,$tid))throw new RuntimeException('Kein Tenant-Zugriff.');$m=$this->manifest($app);if($app==='csv-reporting'){[$ok,$msg]=$this->remoteCheck($cfg);if(!$ok)throw new RuntimeException($msg);}$id=$this->id();@mkdir($this->cfg['state'].'/instances/'.$id,0770,true);file_put_contents($this->cfg['state'].'/instances/'.$id.'/config.json',json_encode($cfg,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));$q=$this->db->prepare('INSERT INTO app_instances VALUES(?,?,?,?,?,?)');$q->execute([$id,$tid,$app,$name,$m['version'],gmdate('c')]);if($mode!=='none'){$type=$mode==='user'?'user':'tenant';$subject=$type==='user'?$u['id']:$tid;foreach(['view','manage'] as $p){$q=$this->db->prepare('INSERT INTO app_access VALUES(?,?,?,?,?,?)');$q->execute([$this->id(),$id,$type,$subject,$app.'.'.$p,gmdate('c')]);}}return$id;}
 public function save(string $id,array $cfg):void{$i=$this->instance($id);if($i['app_id']==='csv-reporting'){[$ok,$msg]=$this->remoteCheck($cfg);if(!$ok)throw new RuntimeException($msg);}$dir=$this->cfg['state'].'/instances/'.$id;@mkdir($dir.'/history',0770,true);if(is_file($dir.'/config.json'))copy($dir.'/config.json',$dir.'/history/'.gmdate('YmdHis').'.json');file_put_contents($dir.'/config.json',json_encode($cfg,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));}
}
